# Read all habit notes and extract data
import re

habit_rows = []  # list of (date_str, dict of habit->value)
habit_order = None

for nid in habit_note_ids:
    note = apis.simple_note.show_note(access_token=access_token, note_id=nid)
    # Extract date from title: "Habit Tracking Log for 2023-05-17"
    m = re.search(r'for (\d{4}-\d{2}-\d{2})', note['title'])
    if not m:
        continue
    date_str = m.group(1)
    # Parse content lines: "habit: yes/no"
    values = {}
    for line in note['content'].splitlines():
        line = line.strip()
        if ':' in line:
            parts = line.split(':', 1)
            if len(parts) == 2:
                habit = parts[0].strip()
                val = parts[1].strip().lower()
                if val in ('yes', 'no'):
                    values[habit] = val
    if habit_order is None:
        # Get order from first note's content lines (in order they appear)
        habit_order = []
        for line in note['content'].splitlines():
            line = line.strip()
            if ':' in line:
                parts = line.split(':', 1)
                if len(parts) == 2:
                    habit = parts[0].strip()
                    val = parts[1].strip().lower()
                    if val in ('yes', 'no'):
                        habit_order.append(habit)
    habit_rows.append((date_str, values))

print("Habit order:", habit_order)
print("Number of rows:", len(habit_rows))
print("First row:", habit_rows[0])

